mapper.insert:
insert into academic_agent_session (
  session_id, user_id, title, task_type, last_message, create_time, update_time
) values (
  #{sessionId}, #{userId}, #{title}, #{taskType}, #{lastMessage}, #{createTime}, #{updateTime}
)
on duplicate key update session_id = values(session_id)

mapper.update:
update academic_agent_session
set title = #{title},
    task_type = #{taskType},
    last_message = #{lastMessage},
    update_time = #{updateTime}
where session_id = #{sessionId}
  and user_id = #{userId}

mapper.insert:
insert into academic_agent_message (
  message_id, session_id, user_id, role, content, image_url, create_time
) values (
  #{messageId}, #{sessionId}, #{userId}, #{role}, #{content}, #{imageUrl}, #{createTime}
)

mapper.select:
select message_id, session_id, user_id, role, content, image_url, create_time
from academic_agent_message
where user_id = #{userId}
  and session_id = #{sessionId}
order by create_time asc, id asc

select session_id, user_id, title, task_type, last_message, create_time, update_time
from academic_agent_session
where user_id = #{userId}
  and session_id = #{sessionId}
limit 1

select session_id, user_id, title, task_type, last_message, create_time, update_time
from academic_agent_session
where user_id = #{userId}
order by update_time desc
limit #{limit}

mapper.delete:
delete from academic_agent_session
where user_id = #{userId}
  and session_id = #{sessionId}

delete from academic_agent_message
where user_id = #{userId}
  and session_id = #{sessionId}

delete from academic_agent_file
where user_id = #{userId}
  and session_id = #{sessionId}

delete from academic_agent_artifact
where user_id = #{userId}
  and session_id = #{sessionId}

mapper.insert:
insert into academic_agent_file (
  file_id, user_id, session_id, file_name, file_type, file_size, object_url, content, summary, status, create_time
) values (
  #{fileId}, #{userId}, #{sessionId}, #{fileName}, #{fileType}, #{fileSize}, #{objectUrl}, #{content},
  #{summary}, #{status}, #{createTime}
)

mapper.select:
select file_id, user_id, session_id, file_name, file_type, file_size, object_url, content, summary, status, create_time
from academic_agent_file
where user_id = #{userId}
  and file_id = #{fileId}
limit 1

select file_id, user_id, session_id, file_name, file_type, file_size, object_url, content, summary, status, create_time
from academic_agent_file
where user_id = #{userId}
order by create_time desc, id desc
limit #{limit}

select file_id, user_id, session_id, file_name, file_type, file_size, object_url, content, summary, status, create_time
from academic_agent_file
where user_id = #{userId}
  and session_id = #{sessionId}
order by create_time desc, id desc

mapper.delete:
delete from academic_agent_file
where user_id = #{userId}
  and file_id = #{fileId}

mapper.select:
select artifact_id, session_id, user_id, run_id, tool_invocation_id, source_type, source_name,
       artifact_type, title, content, download_url, create_time
from academic_agent_artifact
where user_id = #{userId}
  and session_id = #{sessionId}
order by create_time desc, id desc

mapper.insert:
insert into academic_llm_invocation (
  invocation_id, run_id, request_id, session_id, user_id, model_name, prompt_summary,
  response_text, status, prompt_tokens, completion_tokens, total_tokens, fallback_used,
  error_message, started_at, finished_at, latency_millis
) values (
  #{invocationId}, #{runId}, #{requestId}, #{sessionId}, #{userId}, #{modelName}, #{promptSummary},
  #{responseText}, #{status}, #{promptTokens}, #{completionTokens}, #{totalTokens}, #{fallbackUsed},
  #{errorMessage}, #{startedAt}, #{finishedAt}, #{latencyMillis}
)
on duplicate key update invocation_id = values(invocation_id)

insert into academic_tool_invocation (
  invocation_id, run_id, request_id, session_id, user_id, tool_call_id, tool_name, action,
  arguments_json, result_summary, result_json, status, retry_count, error_message,
  started_at, finished_at, latency_millis
) values (
  #{invocationId}, #{runId}, #{requestId}, #{sessionId}, #{userId}, #{toolCallId}, #{toolName}, #{action},
  #{argumentsJson}, #{resultSummary}, #{resultJson}, #{status}, #{retryCount}, #{errorMessage},
  #{startedAt}, #{finishedAt}, #{latencyMillis}
)
on duplicate key update invocation_id = values(invocation_id)

mapper.select:
select run_id, session_id, project_id, request_id, user_id, task_type, question, status, model_name,
       final_summary, error_code, error_message, started_at, finished_at, duration_millis,
       create_time, update_time
from academic_agent_run
where user_id = #{userId}
  and session_id = #{sessionId}
order by started_at desc, id desc
limit #{limit}
